import java.util.Scanner;

// 1. Open the communication channel to the keyboard
Scanner input = new Scanner(System.in);

System.out.print("Enter your name: ");
// 2. Halts the program and waits for the user to type and press ENTER
String name = input.nextLine(); 

System.out.println("Welcome, " + name);

// ❌ THE FATAL TRAP:
int age = input.nextInt(); // User types "20" and hits Enter.
String name = input.nextLine(); // SKIPS! Reads the leftover Enter key.

// ✅ THE ARCHITECT'S SOLUTION:
int age = input.nextInt();
input.nextLine(); // Clear the phantom Enter key from the buffer!
String name = input.nextLine(); // Works perfectly.

